using LittleLeo.Events;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RefreshAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/Refresh Action")]
public class RefreshAction : BattleAction
{
	[Header("Action Specifics")]
	[SerializeField]
	private VoidEvent OnResetUsedRunes;

	public VoidEvent OnResetUsedRunesPublic => OnResetUsedRunes;

	public override void Cast(GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.TryEnterNoInteractionState();
		OnResetUsedRunes.Raise();
		ReferenceSingleton<GameStateManager>.Instance.TryEnterChooseActionState();
	}
}
